export function calculateTotal(price, quantity) {
  if (!Number.isFinite(price) || !Number.isInteger(quantity) || price < 0 || quantity < 0) {
    throw new TypeError('Invalid price or quantity');
  }
  return price * quantity;
}
console.assert(calculateTotal(12, 3) === 36);
console.assert(calculateTotal(12, 0) === 0);
try {
  calculateTotal(12, -1);
  throw new Error('Expected validation failure');
} catch (error) {
  if (!(error instanceof TypeError)) throw error;
}
console.log('Checks passed');

import assert from 'node:assert/strict';
import { calculateTotal } from './validation.mjs';
assert.equal(calculateTotal(12, 3), 36);
assert.equal(calculateTotal(12, 0), 0);
