  for (const task of tasks) {
    if (task.ownerId === ownerId) result.push({ id: task.id, title: task.title });
  }
  return result;
}
console.log(publicTasks([{id:1,title:"Read",ownerId:7},{id:2,title:"Write",ownerId:8}],7));

